<script setup lang="ts">
import { computed,ref } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import FeatureLayout from '../../components/FeatureLayout.vue'
import AppSheet from '../../components/AppSheet.vue'
import { api } from '../../services/api'
import { config } from '../../config'
import { readDemoWallet,redeemDemoProduct } from '../../services/demo-wallet'
import type { Character,Product } from '../../types/domain'
import { errorMessage,goPage,requireSession,showMessage } from '../../utils/navigation'
const roles=ref<Character[]>([]),products=ref<Product[]>([]),wallet=ref(readDemoWallet()),balance=ref(0),filter=ref('全部伙伴'),error=ref(''),confirm=ref<Product|null>(null)
const visibleProducts=computed(()=>filter.value==='温暖治愈'?[]:products.value)
onShow(async()=>{if(!requireSession())return;try{const result=await Promise.all([api.characters(),api.products(),api.home()]);roles.value=result[0];products.value=result[1];balance.value=result[2].user.balance;wallet.value=readDemoWallet()}catch(e){error.value=errorMessage(e)}})
function redeem(){if(!confirm.value)return;if(!config.useMock){showMessage('兑换服务尚未开放');return}try{wallet.value=redeemDemoProduct(confirm.value.id);balance.value=wallet.value.balance;confirm.value=null;showMessage('体验兑换完成，装扮已解锁')}catch(e){error.value=errorMessage(e)}}
</script>
<template><FeatureLayout title="角色商城" subtitle="遇见伙伴，让故事有更多可能"><view class="page-content"><view class="chip-list"><button v-for="item in ['全部伙伴','国风奇幻','温暖治愈']" :key="item" class="chip" :class="{selected:filter===item}" @tap="filter=item">{{item}}</button></view><view class="paper-panel shop-banner section-gap"><text class="section-title serif">山海同行 · 伙伴集</text><text class="copy">让勇敢、温柔与想象，陪你走进新的故事。</text></view><text v-if="error" class="error-copy">{{error}}</text><view class="paper-panel product-card section-gap"><image :src="roles[1]?.avatarUrl||'/static/figma/ai-avatar.png'" mode="aspectFit"/><view><text class="product-name serif">灵墨</text><text class="small-note">温柔的故事伴读者</text><text class="pill violet spaced">已拥有</text><button class="outline-button full-button" @tap="goPage('role-detail',{id:'demo-char-002'})">查看伙伴</button></view></view><view v-for="product in visibleProducts" :key="product.id" class="paper-panel product-card section-gap"><image :src="product.imageUrl" mode="aspectFill"/><view><text class="product-name serif">{{product.name}}</text><text class="small-note">{{product.description}}</text><text class="soft-label">{{wallet.ownedProductIds.includes(product.id)?'已解锁':product.price+' 灵感币'}}</text><button class="warm-button" :disabled="wallet.ownedProductIds.includes(product.id)" @tap="confirm=product">{{wallet.ownedProductIds.includes(product.id)?'已拥有':'查看兑换'}}</button></view></view><text class="wallet-note">我的灵感币 · {{balance}}</text><text class="small-note">{{config.useMock?'当前为本地体验兑换，不发起支付。':'商品和权益以账号服务为准。'}}</text></view><AppSheet title="确认兑换" :open="!!confirm" @close="confirm=null"><text class="section-title serif">{{confirm?.name}}</text><text class="copy">{{confirm?.description}}</text><text class="copy spaced">需要 {{confirm?.price}} 灵感币，当前余额 {{balance}}。</text><text class="small-note spaced">本地体验兑换只更新这台设备的演示余额和解锁状态。</text><button class="warm-button full-button" :disabled="!config.useMock" @tap="redeem">体验兑换</button></AppSheet></FeatureLayout></template>
<style scoped>.shop-banner{background:#fff1c5;border-color:#e1c792}.product-card{display:flex;align-items:center;gap:26rpx;padding:26rpx}.product-card>image{width:185rpx;height:205rpx;border-radius:22rpx;background:#f3ecff}.product-card>view{flex:1;min-width:0}.product-name{display:block;font-size:38rpx;margin-bottom:12rpx}.product-card .warm-button{font-size:24rpx;padding:18rpx}.wallet-note{display:block;text-align:center;font-size:29rpx;color:#a56928;font-weight:700;margin:38rpx 0 20rpx}</style>
